          '<span style="color:#B45309;font-size:18px;flex:none">' + (dir ? "\u2718" : "\u203a") + "</span></div>";
          if (banner.__ycHtml !== bannerHtml) { banner.innerHTML = bannerHtml; banner.__ycHtml = bannerHtml; }
        banner.onclick = function () { openDirModal(false); };
