          btn.innerHTML = '<span style="display:flex;align-items:center;gap:10px;min-width:0"><span style="font-size:22px;flex:none">📊</span><span style="min-width:0"><span style="display:block;font-size:14px;font-weight:700;color:#202020">个人数据看板</span><span style="display:block;font-size:12px;color:#8A8378;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">累计刷题 · 正确率 · 学习时长 · 近7天趋势</span></span></span><span style="color:#8A8378;font-size:18px;flex:none">›</span>';
